#include <cstdio>
#include <numeric>

int main() {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;

    long long result = 0;

    for (long long m = 2; m * m + 1 <= n; ++m) {
        for (long long k = 1; k < m; ++k) {
            long long hypotenuse = m * m + k * k;
            if (hypotenuse > n) break;

            if (((m - k) & 1) && std::gcd(m, k) == 1) {
                result += n / hypotenuse;
            }
        }
    }

    printf("%lld\n", result);
    return 0;
}

