#include <cstdio>
#include <vector>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);

    long long maxSquare = 1LL * n * n;
    vector<bool> isSquare(static_cast<size_t>(maxSquare + 1), false);

    for (long long k = 1; k <= n; ++k)
        isSquare[static_cast<size_t>(k * k)] = true;

    long long result = 0;
    for (long long i = 1; i <= n; ++i) {
        for (long long j = i; j <= n; ++j) {
            long long sum = i * i + j * j;
            if (sum > maxSquare)
                break;
            if (isSquare[static_cast<size_t>(sum)])
                ++result;
        }
    }

    printf("%lld\n", result);
    return 0;
}

